script:
// What in the workspace needs an administrator now (one/home.py, attention).
// Nothing, and the block takes no room on Home.
frappe.xcall("onedesk.one.home.attention").then((rows) => {
	const box = root_element.querySelector(".one-needs");
	const block = root_element.host.closest(".ce-block");
	if (!rows.length) {
		if (block) block.style.display = "none";
		return;
	}
	const esc = frappe.utils.escape_html;
	box.innerHTML =
		`<div class="one-needs-head"><span class="h4"><b>${esc(__("The Workspace"))}</b></span></div>` +
		rows
			.map((one) => `<a class="one-needs-row" href="${esc(one.route)}">${frappe.ui.alert.html({ title: one.what, description: one.detail, theme: "yellow" })}</a>`)
			.join("");
	// frappe's icons are a sprite in the page, which a shadow root cannot
	// reach: the alert's words carry it without one.
	box.querySelectorAll(".es-alert svg").forEach((icon) => icon.remove());
});

style:
/* As a workspace header draws (desktop.scss, .ce-header .h4). */
.one-needs { margin: 0 -7px; }
.one-needs-head { margin: 0 0 12px; }
.one-needs-head .h4 { font-size: var(--text-lg); color: var(--text-light); }
.one-needs-row { display: block; margin-bottom: 8px; text-decoration: none; color: inherit; }
.one-needs-row:hover { text-decoration: none; }

script:
// What needs an operator now (one_admin/home.py, needs), drawn as frappe's
// own quick list widget draws its rows, each with its one action. Drawn
// again when a job, a workspace, a domain or a signup changes anywhere.
const box = root_element.querySelector(".one-admin-needs");
const esc = frappe.utils.escape_html;
const KINDS = { job: ["red", __("Failed")], signup: ["red", __("Paid, Not Built")], stalled: ["orange", ""], storage: ["orange", ""], price: ["red", ""], model: ["red", ""], update: ["blue", ""], owing: ["orange", __("Owing")], domain: ["orange", __("Domain")] };
let rows = [];

function draw() {
	const body = rows.length
		? rows
				.map((one, i) => {
					const [theme, ours] = KINDS[one.kind] || ["gray", one.kind];
					const word = one.badge || ours;
					const why = [one.why, one.detail].filter(Boolean).map(esc).join(" · ");
					const when = one.since ? ` · ${esc(frappe.datetime.prettyDate(one.since))}` : "";
					const act = one.action ? `<button class="btn btn-xs btn-default one-admin-act" data-act="${i}">${esc(one.action.label)}</button>` : "";
					return `<div class="quick-list-item" data-open="${i}">
						<div class="ellipsis left">
							<div class="ellipsis title" title="${esc(one.title)}">${esc(one.title)}</div>
							<div class="timestamp text-muted ellipsis">${why}${when}</div>
						</div>
						${frappe.ui.badge.html({ label: word, theme, css_class: "status" })}
						${act}
					</div>`;
				})
				.join("")
		: `<div class="list-no-data-state text-muted">${esc(__("Nothing needs you."))}</div>`;
	box.innerHTML = `<div class="widget quick-list-widget-box">
		<div class="widget-head"><div class="widget-label"><div class="widget-title">${esc(__("Needs You"))}${rows.length ? ` · ${rows.length}` : ""}</div></div></div>
		<div class="widget-body">${body}</div>
	</div>`;
}

function load() {
	return frappe.xcall("onedesk.one_admin.home.needs").then((said) => {
		rows = said || [];
		draw();
	});
}

box.addEventListener("click", (e) => {
	const act = e.target.closest("[data-act]");
	if (act) {
		const one = rows[Number(act.dataset.act)];
		act.disabled = true;
		frappe
			.xcall(one.action.method, one.action.args)
			.then(() => frappe.show_alert({ message: __("{0}: done.", [one.action.label]), indicator: "green" }))
			.finally(load);
		return;
	}
	const row = e.target.closest("[data-open]");
	if (row) {
		const one = rows[Number(row.dataset.open)];
		frappe.set_route("Form", one.doctype, one.name);
	}
});

const doctypes = ["Provisioning Job", "Tenant", "Tenant Domain", "Account Request", "AI Model"];
doctypes.forEach((doctype) => frappe.realtime.doctype_subscribe(doctype));
const again = frappe.utils.debounce(load, 800);
frappe.realtime.on("list_update", (data) => {
	if (data && doctypes.includes(data.doctype) && root_element.host.isConnected) again();
});
load();

style:
/* frappe's widget and quick list styles reach the block (desk.bundle.css); a
   workspace draws a number card's border through ancestors a block cannot
   see, so it is said again here, as desktop.scss says it (.number-widget-box). */
.one-admin-needs { margin: 0 -7px; }
.one-admin-needs .widget { padding: 12px; border: 1px solid var(--border-color); }
.one-admin-needs .widget-title { font-weight: var(--weight-medium); font-size: var(--text-sm); }
.one-admin-needs .quick-list-item { gap: 8px; cursor: pointer; }
.one-admin-needs .quick-list-item .left { flex: 1; min-width: 0; }
.one-admin-needs .one-admin-act { flex: none; }
